public class ComputeObject 
{
   private int limit;
   private int val; 


   public ComputeObject() 
   {
      limit = 7; 
      val = 10; 
   } 
   public int sumProd(int limit) 
   {
      int total = 0; 
      for (int val = 0; val < limit; val++) 
      { 
         total += val; 
      } 
      total *= val; 
      return total; 
   }
}

